    native_names: &[(Ecosystem, &str)],
    cfg: &'a ResolvedConfig,
) -> Option<&'a PackageConfig> {
    resolve_package_config(native_names, cfg).or_else(|| {
        cfg.package_sets
            .iter()
            .find(|(pattern, _)| pattern.matches_native(native_names))
            .map(|(_, pcfg)| pcfg)
    })
}

